       // Member not found, inform the user and exit
       await interaction.reply({ content: 'Member not found. Please provide a valid member to ban.', ephemeral: true });
       return;
     }

     // Perform the ban
     await member.ban({ reason: reason });
     await interaction.reply(`Successfully banned ${member.user.tag} for ${reason}.`);
   }
   ```
5. Add the ban command: To add the ban command to the Discord bot, you need to register it with the client. You can do this by adding the command name and its options to the `interactionCreate` event listener:
   ```javascript
   client.on('ready', () => {
     // Register the ban command
     client.registerCommand('ban', {
       description: 'Bans a member from the server',
       options: [
         {
           name: 'member',
           description: 'The member to ban',
           type: 'USER',
           required: true
         },
         {
           name: 'reason',
           description: 'The reason for the ban',
           type: 'STRING',
           required: true
         }
       ]
     });

